const resposta = ($json.sql || $json.output || '').trim();

if (resposta.startsWith('NAO_QUERY|')) {
  return [
    {
      json: {
        mensagem: resposta
          .replace('NAO_QUERY|', '')
          .trim()
      }
    }
  ];
}

const permitido =
  resposta.toUpperCase().startsWith('SELECT') ||
  resposta.toUpperCase().startsWith('WITH');

if (!permitido) {
  return [
    {
      json: {
        mensagem: "Não consegui entender com segurança o que você deseja consultar. Pode reformular a pergunta com mais detalhes?"
      }
    }
  ];
}

return [
  {
    json: {
      sql: resposta
    }
  }
];

// Entrada: { sql: "SELECT ...", userPrompt: "..." }  (ajuste nomes se preciso)
let sql = ($('Extract SQL query').first().json.query || "").trim();

// 1) Remove comentários (-- e /* */) e normaliza espaços
const stripComments = s => {
  // remove /* ... */ (multilinha)
  s = s.replace(/\/\*[\s\S]*?\*\//g, ' ');
  // remove -- até o fim da linha
  s = s.replace(/--.*$/gm, ' ');
  return s;
};
const cleaned = stripComments(sql).replace(/\s+/g, ' ').trim();

const forbidden = /\b(SOMENTE|INSERT|PROVIDED|UPDATE|DELETE|MERGE|CREATE|ALTER|DROP|TRUNCATE|GRANT|REVOKE|COMMENT|VACUUM|COPY|REFRESH|CALL|DO|BEGIN|COMMIT|ROLLBACK|SET|LOCK|CLUSTER|REINDEX|DISCARD)\b/i;
if (forbidden.test(cleaned)) {
  return [{ 
    allowed: false, 
    reason: "Contém comando proibido.", 
    message: "Somente SELECT é permitido. Não posso executar DDL/DML." 
  }];
}

return [{ allowed: true, sql }];

let raw = ($('Extract SQL query').first().json.query || "").trim();
if (typeof raw !== "string") raw = String(raw);

// tira blocos markdown
raw = raw.replace(/```sql|```/gi, "");

// captura apenas a query (SELECT/WITH até ;)
const m = raw.match(/(SELECT|WITH)\b[\s\S]*?;/i);
if (!m) {
  return [{ json: { Erro: "Saída não contém SQL pura", SaidaOriginal: raw } }];
}

return [{ json: { sql: m[0].trim() } }];
